using System;
using System.Collections.Generic;
using System.Text;

namespace XFramework.XConfig.Luban.Editor
{
    /// <summary>
    /// 把解析出的表模型生成为接缝与强类型适配器文本。确定性输出、无时间戳。
    /// </summary>
    internal static class LubanGlueEmitter
    {
        internal const string AutoGeneratedHeader =
            "// <auto-generated by XFramework Luban. Do not edit.>";

        internal static Dictionary<string, string> Emit(
            LubanGeneratedModel model,
            LubanGeneratorSettings settings)
        {
            var files = new Dictionary<string, string>(StringComparer.Ordinal);

            if (settings.GenerateSeams)
            {
                var emitted = new HashSet<string>(StringComparer.Ordinal);

                foreach (var table in model.Tables)
                {
                    if (table.Shape != LubanTableShape.Map &&
                        table.Shape != LubanTableShape.IndexedList)
                    {
                        continue;
                    }

                    if (!emitted.Add(table.RowTypeFullName))
                    {
                        continue;
                    }

                    files["Seams/" + Sanitize(table.RowTypeFullName) + ".g.cs"] = EmitSeam(table);
                }
            }

            files["Adapter/" + settings.AdapterClassName + ".g.cs"] = EmitAdapter(model, settings);
            return files;
        }

        internal static string EmitAdapter(
            LubanGeneratedModel model,
            LubanGeneratorSettings settings)
        {
            bool json = settings.CodeTarget == LubanCodeTarget.CsSimpleJson;
            string extension = json ? ".json" : ".bytes";

            var builder = new StringBuilder(4096);
            Line(builder, AutoGeneratedHeader);
            Line(builder, "// Generated from Luban output. Regenerate via the XFramework/Luban menu.");

            bool hasNamespace = !string.IsNullOrEmpty(settings.AdapterNamespace);
            string outer = hasNamespace ? "    " : string.Empty;
            string inner = outer + "    ";

            if (hasNamespace)
            {
                Line(builder, "namespace " + settings.AdapterNamespace);
                Line(builder, "{");
            }

            Line(builder, outer + "public sealed class " + settings.AdapterClassName +
                         " : global::XFramework.XConfig.Luban.ILubanConfigAdapter");
            Line(builder, outer + "{");
            Line(builder, inner + "public string DataFileExtension => \"" + extension + "\";");
            builder.Append('\n');

            Line(builder, inner + "public global::System.Collections.Generic.IReadOnlyList<string> TableNames => new string[]");
            Line(builder, inner + "{");
            foreach (var table in model.Tables)
            {
                Line(builder, inner + "    \"" + EscapeString(table.OutputDataName) + "\",");
            }

            Line(builder, inner + "};");
            builder.Append('\n');

            Line(builder, inner + "public object CreateTables(global::System.Func<string, byte[]> loadBytes)");
            if (json)
            {
                Line(builder, inner + "    => new global::" + model.TablesFullName +
                             "(name => global::Luban.SimpleJSON.JSON.Parse(" +
                             "global::System.Text.Encoding.UTF8.GetString(loadBytes(name))));");
            }
            else
            {
                Line(builder, inner + "    => new global::" + model.TablesFullName +
                             "(name => new global::Luban.ByteBuf(loadBytes(name)));");
            }

            builder.Append('\n');

            Line(builder, inner + "public void RegisterToConfigManager(object tables)");
            Line(builder, inner + "{");
            Line(builder, inner + "    var t = (global::" + model.TablesFullName + ")tables;");
            foreach (var table in model.Tables)
            {
                switch (table.Shape)
                {
                    case LubanTableShape.Map:
                        Line(builder, inner + "    global::XFramework.XConfig.Luban.LubanConfigBridge.RegisterTable(t." +
                                     table.PropertyName + ".DataMap);");
                        break;
                    case LubanTableShape.SingleRow:
                        Line(builder, inner + "    global::XFramework.XConfig.Luban.LubanConfigBridge.RegisterGlobal(t." +
                                     table.PropertyName + ".Data);");
                        break;
                    case LubanTableShape.IndexedList:
                        Line(builder, inner + "    global::XFramework.XConfig.Luban.LubanConfigBridge.RegisterTable(t." +
                                     table.PropertyName + ".DataList, row => " + table.RowExpression + ");");
                        break;
                    case LubanTableShape.PureList:
                        Line(builder, inner + "    // " + table.PropertyName +
                                     "：纯列表表，无主键，未注册到 ConfigManager");
                        break;
                }
            }

            Line(builder, inner + "}");
            builder.Append('\n');

            Line(builder, inner + "public void UnregisterFromConfigManager()");
            Line(builder, inner + "{");
            var unloaded = new HashSet<string>(StringComparer.Ordinal);
            foreach (var table in model.Tables)
            {
                if (table.Shape == LubanTableShape.PureList)
                {
                    continue;
                }

                if (!unloaded.Add(table.RowTypeFullName))
                {
                    continue;
                }

                Line(builder, inner + "    global::XFramework.XConfig.Luban.LubanConfigBridge.Unload<global::" +
                             table.RowTypeFullName + ">();");
            }

            Line(builder, inner + "}");
            Line(builder, outer + "}");

            if (hasNamespace)
            {
                Line(builder, "}");
            }

            return builder.ToString();
        }

        internal static string EmitSeam(LubanGeneratedTable table)
        {
            var builder = new StringBuilder(1024);
            Line(builder, AutoGeneratedHeader);
            Line(builder, "// Seam for " + table.RowTypeFullName +
                         " (Luban table " + table.OutputDataName + ").");

            bool hasNamespace = !string.IsNullOrEmpty(table.RowNamespace);
            string outer = hasNamespace ? "    " : string.Empty;
            string inner = outer + "    ";

            if (hasNamespace)
            {
                Line(builder, "namespace " + table.RowNamespace);
                Line(builder, "{");
            }

            string accessibility = string.IsNullOrEmpty(table.RowAccessibility)
                ? "public"
                : table.RowAccessibility;
            string kind = table.RowIsClass ? "class" : "struct";
            string keyType = table.KeyTypeText;

            Line(builder, outer + accessibility + " partial " + kind + " " + table.RowTypeName +
                         " : global::XFramework.XConfig.IConfigRow<" + keyType + ">");
            Line(builder, outer + "{");
            Line(builder, inner + keyType + " global::XFramework.XConfig.IConfigRow<" + keyType +
                         ">.Id => " + table.IdExpression + ";");
            Line(builder, outer + "}");

            if (hasNamespace)
            {
                Line(builder, "}");
            }

            return builder.ToString();
        }

        internal static string Sanitize(string value)
        {
            var builder = new StringBuilder(value.Length);
            foreach (char c in value)
            {
                builder.Append(char.IsLetterOrDigit(c) || c == '_' ? c : '_');
            }

            return builder.ToString();
        }

        private static string EscapeString(string value)
        {
            return value.Replace("\\", "\\\\").Replace("\"", "\\\"");
        }

        private static void Line(StringBuilder builder, string value)
        {
            builder.Append(value);
            builder.Append('\n');
        }
    }
}
